import {readFile,writeFile,mkdir} from 'node:fs/promises';
import {PrismaClient} from '@prisma/client';
import {loadConfig} from '../src/modules/operations/config.js';
import {draftSchema,json} from '../src/modules/compliance/contracts.js';
// @ts-ignore Static prototype JavaScript has no declaration file.
import {checklistGuide} from '../../../../Prototype/dist/checklist-guide.js';
// @ts-ignore Static prototype JavaScript has no declaration file.
import {draftPriority} from '../../../../Prototype/dist/reviewer-controls.js';

// Same legal offsets, but the period is generated by the engine instead of a date the company types each period.
// Shift on non-working days is deliberately NOT added here: that needs a legal basis checked by the reviewer.
export function convertDeadline(d:any){
 const keep=d.shift?{shift:d.shift}:{};
 if(d.kind==='PERIOD_END'&&['vatMonthlyPeriodEndDate','socialInsuranceContributionPeriodEndDate'].includes(d.periodEndFact))return {kind:'MONTHLY',monthsAfterEnd:d.monthsAfterEnd,day:d.day,...keep};
 if(d.kind==='PERIOD_END'&&d.periodEndFact==='vatQuarterPeriodEndDate')return {kind:'QUARTERLY',monthsAfterEnd:d.monthsAfterEnd,day:d.day,...keep};
 if(d.kind==='DATE_OFFSET'&&d.triggerFact==='accountingFiscalYearEndDate')return {kind:'FISCAL_YEAR_END_OFFSET',months:d.months??0,days:d.days??0,...keep};
 return null;
}
const PERIODIC_TEXT=/hằng tháng|hàng tháng|hằng quý|hàng quý|hằng năm|hàng năm|định kỳ|sáu tháng|6 tháng|chậm nhất|trước ngày|trong thời hạn|trong vòng \d+ ngày|ngày \d+ (của )?tháng/iu;
export function worklist(content:any,citations:any[]){
 const text=[content.title,content.action,...content.steps].join(' '),guide=checklistGuide(content),items:string[]=[];
 if(content.deadline.kind==='NONE'&&PERIODIC_TEXT.test(text))items.push('Nội dung nhắc tới thời hạn/kỳ nhưng deadline đang là NONE: xác định kiểu hạn (MONTHLY/QUARTERLY/ANNUAL/...) từ căn cứ.');
 if(['MONTHLY','QUARTERLY','FISCAL_YEAR_END_OFFSET','ANNUAL','DATE_OFFSET'].includes(content.deadline.kind)&&!content.deadline.shift)items.push('Có hạn cụ thể: xác nhận căn cứ có cho lùi sang ngày làm việc kế tiếp khi trùng ngày nghỉ hay không.');
 if(guide.steps.some((s:any)=>/chuyên gia/iu.test(s.detail)))items.push('Có bước viết cho chuyên gia, cần viết lại thành việc doanh nghiệp làm được.');
 if(new Set(guide.steps.map((s:any)=>s.evidence)).size<=1&&guide.steps.length>1)items.push('Bằng chứng giống nhau ở mọi bước: ghi tài liệu cụ thể cho từng bước.');
 if(citations.length>1&&guide.steps.every((s:any)=>!s.provisionIds?.length))items.push(`Có ${citations.length} căn cứ nhưng chưa bước nào gắn điều khoản: gắn provisionIds cho từng bước.`);
 return items;
}
const [mode,a,b]=process.argv.slice(2);
if(mode==='--file'){
 // Offline: transform an exported bundle (no database) for review.
 if(!a||!b)throw Error('Usage: normalize-checklist-drafts.ts --file <draft-obligations.jsonl> <out-dir>');
 const rows=(await readFile(a,'utf8')).split(/\r?\n/).filter(x=>x.trim()).map(x=>JSON.parse(x));const report:any[]=[];
 const out=rows.map((row,i)=>{const deadline=convertDeadline(row.content.deadline);const content={...row.content,...(deadline?{deadline}:{}),...(row.content.guide?{guide:checklistGuide(row.content)}:{})};draftSchema.parse({content,citations:row.citations});
  const p=draftPriority(content);report.push({index:i+1,title:content.title,group:content.group,deadlineBefore:row.content.deadline.kind,deadlineAfter:content.deadline.kind,priority:p.score,priorityReasons:p.reasons,ruleFacts:p.facts,reviewerTodo:worklist(content,row.citations)});return {content,citations:row.citations};});
 await mkdir(b,{recursive:true});
 await writeFile(b+'/draft-obligations.jsonl',out.map(x=>JSON.stringify(x)).join('\n')+'\n');
 await writeFile(b+'/normalize-report.json',JSON.stringify({total:rows.length,deadlinesConverted:report.filter(r=>r.deadlineBefore!==r.deadlineAfter).length,status:'DRAFT',legalTextUnchanged:true,officialPublicationPerformed:false,items:report},null,2));
 console.log(JSON.stringify({total:rows.length,deadlinesConverted:report.filter(r=>r.deadlineBefore!==r.deadlineAfter).length,out:b}));
}else if(mode==='--db'){
 // Only the deadline conversion is written: guide cleanup is applied at display time so pilot progress stays valid.
 if(!a)throw Error('Usage: normalize-checklist-drafts.ts --db <report.json> [--apply]');
 const apply=b==='--apply',db=new PrismaClient({datasources:{db:{url:loadConfig().databaseUrl}}});
 try{
  const rows=await db.obligationVersion.findMany({where:{status:'DRAFT'},include:{citations:true}});const changed:any[]=[];
  for(const v of rows){const content=v.contentJson as any,deadline=convertDeadline(content.deadline);if(!deadline)continue;
   const input=draftSchema.parse({content:{...content,deadline},citations:v.citations.map(({documentId,snapshotId,parseRunId,provisionId,ocrVerified})=>({documentId,snapshotId,parseRunId,provisionId,ocrVerified}))});
   changed.push({versionId:v.id,title:content.title,from:content.deadline,to:deadline});
   if(apply)await db.$transaction(async tx=>{const r=await tx.obligationVersion.updateMany({where:{id:v.id,status:'DRAFT',revision:v.revision},data:{contentJson:json(input.content),revision:{increment:1}}});if(r.count!==1)throw Error('DRAFT_CHANGED');await tx.workspaceAudit.create({data:{actorId:'local-checklist-operator',action:'CHECKLIST_DEADLINE_PERIODIZED',targetId:v.id}});});
  }
  const result={applied:apply,changed:changed.length,items:changed,status:'DRAFT',officialPublicationPerformed:false};
  await writeFile(a,JSON.stringify(result,null,2));console.log(JSON.stringify({applied:apply,changed:changed.length}));
 }finally{await db.$disconnect();}
}else throw Error('Usage: --file <in.jsonl> <out-dir> | --db <report.json> [--apply]');
